#include "hip_api.h"
#include <vector>
int main(int argc,char**argv){try{if(argc!=2)return 2;hip_probe::Api a;a.Check(a.hipInit(0),"init");a.Check(a.hipSetDevice(0),"dev");hip_probe::Handle m{},f{};a.Check(a.LoadModule(&m,argv[1]),"load");a.Check(a.hipModuleGetFunction(&f,m,"byte_probe"),"fn");void*d{};a.Check(a.hipMalloc(&d,256*4),"malloc");void*args[]={&d};a.Check(a.hipModuleLaunchKernel(f,1,1,1,256,1,1,0,nullptr,args,nullptr),"launch");a.Check(a.hipDeviceSynchronize(),"sync");std::vector<unsigned>v(256);a.Check(a.hipMemcpy(v.data(),d,1024,2),"copy");unsigned bad=0;for(unsigned i=0;i<256;i++)if(v[i]!=i){printf("DIFF %02x %02x\n",i,v[i]);bad++;}printf("BYTE_CODES=256 roundtrip_bad=%u\n",bad);a.hipFree(d);a.hipModuleUnload(m);return bad?1:0;}catch(const std::exception&e){fprintf(stderr,"%s\n",e.what());return 2;}}
